import { createFileRoute } from '@tanstack/react-router'
import { json } from '@tanstack/react-start'
import { createPoll } from '../../db'

export const Route = createFileRoute('/api/polls')({
  server: {
    handlers: {
      POST: async ({ request }) => {
        try {
          const body = await request.json()
          const { question, options } = body

          if (!question || typeof question !== 'string' || question.trim() === '') {
            return json({ error: 'Question is required' }, { status: 400 })
          }

          if (!options || !Array.isArray(options)) {
            return json({ error: 'Options must be an array' }, { status: 400 })
          }

          const validOptions = options.map(o => typeof o === 'string' ? o.trim() : '').filter(o => o !== '')
          if (validOptions.length < 2) {
            return json({ error: 'At least 2 non-empty options are required' }, { status: 400 })
          }

          const poll = await createPoll(question.trim(), validOptions)
          return json(poll, { status: 201 })
        } catch (err: any) {
          return json({ error: err.message || 'Invalid request' }, { status: 400 })
        }
      }
    }
  }
})

import { createFileRoute } from '@tanstack/react-router'
import { json } from '@tanstack/react-start'
import { getPoll } from '../../db'

export const Route = createFileRoute('/api/polls/$id')({
  server: {
    handlers: {
      GET: async ({ params }) => {
        try {
          const { id } = params
          if (!id) {
            return json({ error: 'Poll ID is required' }, { status: 400 })
          }
          const poll = await getPoll(id)
          if (!poll) {
            return json({ error: 'Poll not found' }, { status: 404 })
          }
          return json(poll, { status: 200 })
        } catch (err: any) {
          return json({ error: err.message || 'Internal server error' }, { status: 500 })
        }
      }
    }
  }
})

import { createFileRoute } from '@tanstack/react-router'
import { json } from '@tanstack/react-start'
import crypto from 'crypto'
import { castVote } from '../../../db'

export const Route = createFileRoute('/api/polls/$id/vote')({
  server: {
    handlers: {
      POST: async ({ request, params }) => {
        try {
          const { id } = params // pollId
          if (!id) {
            return json({ error: 'Poll ID is required' }, { status: 400 })
          }

          let body
          try {
            body = await request.json()
          } catch (e) {
            return json({ error: 'Invalid JSON body' }, { status: 400 })
          }

          const { optionId } = body
          if (!optionId || typeof optionId !== 'string') {
            return json({ error: 'Option ID is required' }, { status: 400 })
          }

          // Parse client_id cookie
          const cookieHeader = request.headers.get('cookie') || ''
          const match = cookieHeader.match(/(?:^|; )client_id=([^;]*)/)
          let clientId = match ? match[1] : null

          if (!clientId) {
            clientId = crypto.randomUUID()
          }

          // Cast vote
          const poll = await castVote(id, optionId, clientId)

          // Success: Return 200 with updated poll and set cookie
          const headers = new Headers()
          headers.set('Set-Cookie', `client_id=${clientId}; Path=/; HttpOnly; Max-Age=31536000; SameSite=Lax`)
          return json(poll, { status: 200, headers })
        } catch (err: any) {
          if (err.message === 'POLL_NOT_FOUND' || err.message === 'OPTION_NOT_FOUND') {
            return json({ error: 'Poll or option not found' }, { status: 404 })
          }
          if (err.message === 'ALREADY_VOTED') {
            return json({ error: 'You have already voted on this poll' }, { status: 409 })
          }
          return json({ error: err.message || 'Internal server error' }, { status: 500 })
        }
      }
    }
  }
})

import { createServerFn } from '@tanstack/react-start'
import { listAllPolls, getPoll, createPoll, hasClientVoted } from './db'
import { getCookie } from '@tanstack/react-start/server'

export const getPollsFn = createServerFn({ method: 'GET' })
  .handler(async () => {
    return await listAllPolls()
  })

export const getPollFn = createServerFn({ method: 'GET' })
  .validator((id: string) => id)
  .handler(async ({ data: id }) => {
    const poll = await getPoll(id)
    if (!poll) return null

    // Check if current client has voted
    const clientId = getCookie('client_id')
    let hasVoted = false
    if (clientId) {
      hasVoted = await hasClientVoted(id, clientId)
    }

    return {
      poll,
      hasVoted
    }
  })

export const createPollFn = createServerFn({ method: 'POST' })
  .validator((data: { question: string; options: string[] }) => data)
  .handler(async ({ data }) => {
    return await createPoll(data.question, data.options)
  })

import { createFileRoute, Link, useRouter } from '@tanstack/react-router'
import { useState } from 'react'
import { getPollsFn, createPollFn } from '../server-fns'

export const Route = createFileRoute('/')({
  loader: async () => {
    return await getPollsFn()
  },
  component: HomeComponent,
})

function HomeComponent() {
  const polls = Route.useLoaderData()
  const router = useRouter()
  const [question, setQuestion] = useState('')
  const [options, setOptions] = useState(['', ''])
  const [error, setError] = useState<string | null>(null)

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...options]
    newOptions[index] = value
    setOptions(newOptions)
  }

  const addOptionField = () => {
    setOptions([...options, ''])
  }

  const removeOptionField = (index: number) => {
    if (options.length <= 2) return
    const newOptions = options.filter((_, i) => i !== index)
    setOptions(newOptions)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)

    const trimmedQuestion = question.trim()
    const trimmedOptions = options.map(o => o.trim()).filter(o => o !== '')

    if (!trimmedQuestion) {
      setError('Question is required')
      return
    }

    if (trimmedOptions.length < 2) {
      setError('At least 2 non-empty options are required')
      return
    }

    try {
      const newPoll = await createPollFn({
        data: {
          question: trimmedQuestion,
          options: trimmedOptions,
        }
      })

      // Clear form
      setQuestion('')
      setOptions(['', ''])

      // Refresh list and navigate
      await router.invalidate()
      window.location.href = `/poll/${newPoll.id}`
    } catch (err: any) {
      setError(err.message || 'Failed to create poll')
    }
  }

  return (
    <div>
      <h1>Real-Time Polling App</h1>

      <div style={{ marginBottom: '40px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Create a New Poll</h2>
        {error && <div style={{ color: 'red', marginBottom: '10px' }}>{error}</div>}

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '5px' }}>Question:</label>
            <input
              type="text"
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder="What is your favorite programming language?"
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>

          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '5px' }}>Options:</label>
            {options.map((option, index) => (
              <div key={index} style={{ display: 'flex', marginBottom: '10px' }}>
                <input
                  type="text"
                  value={option}
                  onChange={(e) => handleOptionChange(index, e.target.value)}
                  placeholder={`Option ${index + 1}`}
                  style={{ flex: 1, padding: '8px' }}
                  required={index < 2}
                />
                {options.length > 2 && (
                  <button
                    type="button"
                    onClick={() => removeOptionField(index)}
                    style={{ marginLeft: '10px', padding: '8px 12px', background: '#ff4d4d', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Remove
                  </button>
                )}
              </div>
            ))}
            <button
              type="button"
              onClick={addOptionField}
              style={{ padding: '8px 12px', background: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
            >
              + Add Option
            </button>
          </div>

          <button
            type="submit"
            style={{ padding: '10px 20px', background: '#28a745', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '16px' }}
          >
            Create Poll
          </button>
        </form>
      </div>

      <h2>Existing Polls</h2>
      {polls.length === 0 ? (
        <p>No polls created yet. Be the first to create one!</p>
      ) : (
        <ul style={{ listStyleType: 'none', padding: 0 }}>
          {polls.map((poll) => (
            <li key={poll.id} style={{ padding: '15px', border: '1px solid #eee', marginBottom: '10px', borderRadius: '4px' }}>
              <Link to={`/poll/${poll.id}`} style={{ textDecoration: 'none', color: '#007bff', fontSize: '18px', fontWeight: 'bold' }}>
                {poll.question}
              </Link>
              <div style={{ color: '#666', marginTop: '5px' }}>
                Total Votes: {poll.totalVotes}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

import { createFileRoute, Link } from '@tanstack/react-router'
import { useState, useEffect } from 'react'
import { getPollFn } from '../server-fns'

export const Route = createFileRoute('/poll/$id')({
  loader: async ({ params }) => {
    const data = await getPollFn({ data: params.id })
    if (!data) {
      throw new Error('Poll not found')
    }
    return data
  },
  component: PollComponent,
  errorComponent: () => (
    <div>
      <h2>Poll Not Found</h2>
      <p>The poll you are looking for does not exist or has been deleted.</p>
      <Link to="/" style={{ color: '#007bff' }}>Go back to home page</Link>
    </div>
  )
})

function PollComponent() {
  const initialData = Route.useLoaderData()
  const { id } = Route.useParams()

  const [poll, setPoll] = useState(initialData.poll)
  const [hasVoted, setHasVoted] = useState(initialData.hasVoted)
  const [voteError, setVoteError] = useState<string | null>(null)

  // Sync state with loader data
  useEffect(() => {
    setPoll(initialData.poll)
    setHasVoted(initialData.hasVoted)
  }, [initialData])

  // Real-time polling updates every 2 seconds
  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const data = await getPollFn({ data: id })
        if (data && data.poll) {
          setPoll(data.poll)
          setHasVoted(data.hasVoted)
        }
      } catch (err) {
        console.error('Failed to fetch real-time poll updates:', err)
      }
    }, 2000)

    return () => clearInterval(interval)
  }, [id])

  const getPercent = (votes: number, total: number) => {
    if (total === 0) return 0
    return Math.round((votes / total) * 100)
  }

  const handleVote = async (optionId: string) => {
    setVoteError(null)

    if (hasVoted) {
      setVoteError('You have already voted on this poll')
      return
    }

    try {
      const res = await fetch(`/api/polls/${poll.id}/vote`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ optionId })
      })

      const data = await res.json()

      if (res.status === 200) {
        setPoll(data)
        setHasVoted(true)
      } else if (res.status === 409) {
        setVoteError(data.error || 'You have already voted on this poll')
        setHasVoted(true) // update state to match server
      } else {
        setVoteError(data.error || 'Failed to cast vote')
      }
    } catch (err: any) {
      setVoteError(err.message || 'Network error')
    }
  }

  return (
    <div>
      <div style={{ marginBottom: '20px' }}>
        <Link to="/" style={{ textDecoration: 'none', color: '#007bff' }}>&larr; Back to Polls</Link>
      </div>

      <h1>{poll.question}</h1>

      <div 
        data-testid="total-votes" 
        style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '20px', color: '#555' }}
      >
        Total Votes: {poll.totalVotes}
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {poll.options.map((option) => {
          const percent = getPercent(option.votes, poll.totalVotes)
          return (
            <div 
              key={option.id} 
              style={{ 
                padding: '15px', 
                border: '1px solid #ccc', 
                borderRadius: '8px',
                background: '#f9f9f9',
                position: 'relative',
                overflow: 'hidden'
              }}
            >
              {/* Progress bar background */}
              <div 
                style={{ 
                  position: 'absolute', 
                  top: 0, 
                  left: 0, 
                  bottom: 0, 
                  width: `${percent}%`, 
                  background: 'rgba(40, 167, 69, 0.1)',
                  zIndex: 0,
                  transition: 'width 0.5s ease-in-out'
                }} 
              />

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', position: 'relative', zIndex: 1 }}>
                <div>
                  <span style={{ fontSize: '18px', fontWeight: 'bold', marginRight: '15px' }}>
                    {option.text}
                  </span>
                  <span 
                    data-testid={`count-${option.id}`} 
                    style={{ background: '#eee', padding: '2px 8px', borderRadius: '12px', fontSize: '14px', color: '#666' }}
                  >
                    {option.votes}
                  </span>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <span 
                    data-testid={`percent-${option.id}`} 
                    style={{ fontSize: '18px', fontWeight: 'bold', color: '#28a745' }}
                  >
                    {percent}%
                  </span>

                  <button
                    data-testid={`vote-${option.id}`}
                    onClick={() => handleVote(option.id)}
                    disabled={hasVoted}
                    style={{ 
                      padding: '8px 16px', 
                      background: hasVoted ? '#ccc' : '#28a745', 
                      color: 'white', 
                      border: 'none', 
                      borderRadius: '4px', 
                      cursor: hasVoted ? 'not-allowed' : 'pointer',
                      fontWeight: 'bold'
                    }}
                  >
                    Vote
                  </button>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {voteError && (
        <div 
          data-testid="vote-error" 
          style={{ 
            marginTop: '20px', 
            padding: '15px', 
            background: '#f8d7da', 
            color: '#721c24', 
            border: '1px solid #f5c6cb', 
            borderRadius: '4px',
            fontWeight: 'bold'
          }}
        >
          {voteError}
        </div>
      )}
    </div>
  )
}

